-- Counts follow the caller's existing public catalogue visibility policies.
create or replace function public.catalogue_category_counts()
returns table(sector text,open_jobs bigint) language sql stable security invoker set search_path=public,pg_temp as $$
 select case when canonical_role=any(array['registered-nurse','licensed-practical-nurse','certified-nursing-assistant','medical-assistant','pharmacy-technician','physical-therapist','respiratory-therapist','home-health-aide']::text[]) then 'healthcare'
 when canonical_role=any(array['cdl-truck-driver','delivery-driver','warehouse-associate','forklift-operator','dispatcher','logistics-coordinator']::text[]) then 'transport'
 when canonical_role=any(array['data-analyst','business-analyst','business-intelligence-developer','power-bi-developer','tableau-developer','sql-developer','data-engineer','data-scientist','machine-learning-engineer','software-engineer','full-stack-developer','devops-engineer','cloud-engineer','qa-engineer','cybersecurity-analyst','servicenow-developer','salesforce-developer','anaplan-model-builder']::text[]) then 'tech' end, count(*)
 from public.pre_scraped_jobs where closed_at is null and country='us' and (expires_at is null or expires_at>now())
 and canonical_role=any(array['registered-nurse','licensed-practical-nurse','certified-nursing-assistant','medical-assistant','pharmacy-technician','physical-therapist','respiratory-therapist','home-health-aide','cdl-truck-driver','delivery-driver','warehouse-associate','forklift-operator','dispatcher','logistics-coordinator','data-analyst','business-analyst','business-intelligence-developer','power-bi-developer','tableau-developer','sql-developer','data-engineer','data-scientist','machine-learning-engineer','software-engineer','full-stack-developer','devops-engineer','cloud-engineer','qa-engineer','cybersecurity-analyst','servicenow-developer','salesforce-developer','anaplan-model-builder']::text[]) group by 1
$$;
create or replace function public.catalogue_search_alternatives(p_role text,p_state text)
returns table(kind text,label text,role_name text,state text,open_jobs bigint)
language sql stable security invoker set search_path=public,pg_temp as $$
 with neighbours(code,nearby) as (values ('AL',array['FL','GA','MS','TN']::text[]),('AK',array[]::text[]),('AZ',array['CA','CO','NM','NV','UT']::text[]),('AR',array['LA','MS','MO','OK','TN','TX']::text[]),('CA',array['AZ','NV','OR']::text[]),('CO',array['AZ','KS','NE','NM','OK','UT','WY']::text[]),('CT',array['MA','NY','RI']::text[]),('DE',array['MD','NJ','PA']::text[]),('FL',array['AL','GA']::text[]),('GA',array['AL','FL','NC','SC','TN']::text[]),('HI',array[]::text[]),('ID',array['MT','NV','OR','UT','WA','WY']::text[]),('IL',array['IN','IA','KY','MI','MO','WI']::text[]),('IN',array['IL','KY','MI','OH']::text[]),('IA',array['IL','MN','MO','NE','SD','WI']::text[]),('KS',array['CO','MO','NE','OK']::text[]),('KY',array['IL','IN','MO','OH','TN','VA','WV']::text[]),('LA',array['AR','MS','TX']::text[]),('ME',array['NH']::text[]),('MD',array['DE','PA','VA','WV','DC']::text[]),('MA',array['CT','NH','NY','RI','VT']::text[]),('MI',array['IL','IN','OH','WI']::text[]),('MN',array['IA','ND','SD','WI']::text[]),('MS',array['AL','AR','LA','TN']::text[]),('MO',array['AR','IL','IA','KS','KY','NE','OK','TN']::text[]),('MT',array['ID','ND','SD','WY']::text[]),('NE',array['CO','IA','KS','MO','SD','WY']::text[]),('NV',array['AZ','CA','ID','OR','UT']::text[]),('NH',array['ME','MA','VT']::text[]),('NJ',array['DE','NY','PA']::text[]),('NM',array['AZ','CO','OK','TX','UT']::text[]),('NY',array['CT','MA','NJ','PA','RI','VT']::text[]),('NC',array['GA','SC','TN','VA']::text[]),('ND',array['MN','MT','SD']::text[]),('OH',array['IN','KY','MI','PA','WV']::text[]),('OK',array['AR','CO','KS','MO','NM','TX']::text[]),('OR',array['CA','ID','NV','WA']::text[]),('PA',array['DE','MD','NJ','NY','OH','WV']::text[]),('RI',array['CT','MA','NY']::text[]),('SC',array['GA','NC']::text[]),('SD',array['IA','MN','MT','NE','ND','WY']::text[]),('TN',array['AL','AR','GA','KY','MS','MO','NC','VA']::text[]),('TX',array['AR','LA','NM','OK']::text[]),('UT',array['AZ','CO','ID','NV','NM','WY']::text[]),('VT',array['MA','NH','NY']::text[]),('VA',array['KY','MD','NC','TN','WV','DC']::text[]),('WA',array['ID','OR']::text[]),('WV',array['KY','MD','OH','PA','VA']::text[]),('WI',array['IL','IA','MI','MN']::text[]),('WY',array['CO','ID','MT','NE','SD','UT']::text[]),('DC',array['MD','VA']::text[])),
 roles(id,name) as (values ('data-analyst','Data Analyst'),('business-analyst','Business Analyst'),('business-intelligence-developer','Business Intelligence Developer'),('power-bi-developer','Power BI Developer'),('tableau-developer','Tableau Developer'),('sql-developer','SQL Developer'),('data-engineer','Data Engineer'),('data-scientist','Data Scientist'),('machine-learning-engineer','Machine Learning Engineer'),('software-engineer','Software Engineer'),('full-stack-developer','Full Stack Developer'),('devops-engineer','DevOps Engineer'),('cloud-engineer','Cloud Engineer'),('qa-engineer','QA Engineer'),('cybersecurity-analyst','Cybersecurity Analyst'),('servicenow-developer','ServiceNow Developer'),('salesforce-developer','Salesforce Developer'),('anaplan-model-builder','Anaplan Model Builder'),('product-manager','Product Manager'),('project-manager','Project Manager'),('registered-nurse','Registered Nurse'),('accountant','Accountant'),('marketing-manager','Marketing Manager'),('human-resources-manager','Human Resources Manager'),('sales-representative','Sales Representative'),('customer-service-representative','Customer Service Representative'),('licensed-practical-nurse','Licensed Practical Nurse'),('certified-nursing-assistant','Certified Nursing Assistant'),('medical-assistant','Medical Assistant'),('pharmacy-technician','Pharmacy Technician'),('physical-therapist','Physical Therapist'),('respiratory-therapist','Respiratory Therapist'),('home-health-aide','Home Health Aide'),('cdl-truck-driver','CDL Truck Driver'),('delivery-driver','Delivery Driver'),('warehouse-associate','Warehouse Associate'),('forklift-operator','Forklift Operator'),('dispatcher','Dispatcher'),('logistics-coordinator','Logistics Coordinator'),('nurse-practitioner','Nurse Practitioner')),
 visible as (select canonical_role,state_code,job_title from public.pre_scraped_jobs
   where closed_at is null and country='us' and (expires_at is null or expires_at>now())),
 suggestions as (
 select 'state'::text kind,j.state_code::text label,r.name role_name,j.state_code::text state,count(*) open_jobs
 from visible j join roles r on r.id=j.canonical_role join neighbours n on n.code=p_state
 where j.canonical_role=p_role and j.state_code=any(n.nearby) group by j.state_code,r.name
 union all
 select 'role',r.name,r.name,nullif(p_state,''),count(*)
 from visible j join roles r on r.id=j.canonical_role or (r.id='nurse-practitioner' and j.job_title ~* '\mnurse practitioner\M')
 where r.id<>p_role and (p_state='' or j.state_code=p_state)
 and ((p_role=any(array['registered-nurse','licensed-practical-nurse','certified-nursing-assistant','medical-assistant','pharmacy-technician','physical-therapist','respiratory-therapist','home-health-aide']::text[]) and r.id in ('registered-nurse','licensed-practical-nurse','certified-nursing-assistant','nurse-practitioner'))
 or (p_role=any(array['cdl-truck-driver','delivery-driver','warehouse-associate','forklift-operator','dispatcher','logistics-coordinator']::text[]) and r.id in ('cdl-truck-driver','delivery-driver','warehouse-associate'))
 or (p_role in ('software-engineer','data-engineer','data-analyst','devops-engineer') and r.id in ('software-engineer','data-engineer','data-analyst','devops-engineer')))
 group by r.name
 ) select * from suggestions where open_jobs>0 order by kind,open_jobs desc,label limit 12
$$;
revoke all on function public.catalogue_category_counts(),public.catalogue_search_alternatives(text,text) from public;
grant execute on function public.catalogue_category_counts(),public.catalogue_search_alternatives(text,text) to anon,authenticated;
